{
  "findings": [
    {
      "check_id": "CKV_AWS_210",
      "title": "Ensure AWS Batch Job Definition has a specified IAM Role",
      "resource": "aws_batch_job_definition.pass3",
      "severity": "HIGH",
      "explanation": "The Batch Job Definition does not specify an IAM role, potentially leading to insufficient permissions or privilege escalation."
    }
  ],
  "patched_code": "resource "aws_batch_job_definition" "pass3" {
  name = "tf_test_batch_job_definition"
  type = "container"

  container_properties = jsonencode({
    "command" : ["ls", "-la"],
    "image" : "busybox",
    "memory" : 1024,
    "vcpus" : 1,
    "volumes" : [
      {
        "host" : {
          "sourcePath" : "/tmp"
        },
        "name" : "tmp"
      }
    ],
    "environment" : [
      { "name" : "VARNAME", "value" : "VARVAL" }
    ],
    "mountPoints" : [
      {
        "sourceVolume" : "tmp",
        "containerPath" : "/tmp",
        "readOnly" : false
      }
    ],
    "ulimits" : [
      {
        "hardLimit" : 1024,
        "name" : "nofile",
        "softLimit" : 1024
      }
    ],
    "executionRoleArn": "arn:aws:iam::123456789012:role/AWSBatchJobExecutionRole"
  })
}",
  "fix_summary": "Added an executionRoleArn to the container properties of the AWS Batch Job Definition to ensure it has a specified IAM Role for execution."
}
